"""Submission model.py — Pure scikit-learn baseline (TF-IDF word + char n-grams + Logistic Regression).

Backend contract (per Final Project Submission Guideline §3.2):
  - The backend instantiates `Model()` with no args.
  - It then calls `model.predict(batch)` to get predictions.
  - We return predictions as a list of strings ("FoxNews" or "NBC") to match the labels.

We embed the trained sklearn pipeline as a gzipped+base64-encoded pickle in this file,
so no model.pt is needed. This keeps the upload to just (model.py, preprocess.py).
"""

from __future__ import annotations

import base64
import gzip
import pickle
from pathlib import Path
from typing import Iterable, List, Sequence, Union


# ---------------------------------------------------------------------------
# Embedded sklearn pipeline (gzipped pickle, base64-encoded).
# Generated from models/classical_v2_random.joblib via tools/build_submission.py.
# Loading order: base64-decode → gunzip → pickle.loads → sklearn Pipeline.
# ---------------------------------------------------------------------------

_WEIGHTS_B64 = """"""


def _load_pipeline():
    raw = base64.b64decode(_WEIGHTS_B64.strip())
    return pickle.loads(gzip.decompress(raw))


# Some teams stash a non-Pipeline object; this map normalises predictions.
INT_TO_LABEL = {0: "NBC", 1: "FoxNews"}


class Model:
    """News-source classifier wrapper.

    The backend instantiates this with no arguments, then calls
    `predict(batch)` where `batch` is whatever `preprocess.prepare_data`
    returned for X (a list/array of headline strings in our case).
    """

    def __init__(self) -> None:
        self.pipe = _load_pipeline()

    def predict(self, batch: Union[Sequence[str], Iterable[str]]) -> List[str]:
        # Normalise to a list of strings; the pipeline's TfidfVectorizer
        # accepts lists/iterables of str directly.
        if hasattr(batch, "tolist"):
            batch = batch.tolist()
        if isinstance(batch, str):
            batch = [batch]
        else:
            batch = [str(x) for x in batch]
        preds = self.pipe.predict(batch)
        return [INT_TO_LABEL[int(p)] for p in preds]

    # Allow the backend to call model(batch) instead of model.predict(batch).
    def __call__(self, batch):
        return self.predict(batch)


def get_model() -> Model:
    """Alternative constructor required by the spec."""
    return Model()
